          try {
            const decoded = await ctx.decodeAudioData(
              item.arrayBuffer.slice(0),
            );
            const key = item.id.slice(3),
              split = key.indexOf("::variant::");
            if (split >= 0) {
              const slot = key.slice(0, split);
              (variants[slot] ||= []).push({
                id: item.id,
                name: item.name || "候选音效",
                buffer: decoded,
              });
            } else customFxBuffers[key] = decoded;
          } catch (_) {}
        }),
      );

